SELECT SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) / 1000 AS VALOR_ATUAL,       SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) / 1000 AS VALOR_ANTERIORFROM IMP_BASE_BALANCETEWHERE CODEMP = :VAR_EMPRESA_DRE  AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%')  AND (      YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) OR      YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR))  )